package com.vandorlabs.neoforge.infuser;
import com.vandorlabs.neoforge.infuser.client.*;import com.vandorlabs.neoforge.rack.NativeBatteryModule;import net.minecraft.client.Minecraft;import net.minecraft.core.*;import net.minecraft.world.InteractionHand;import net.minecraft.world.inventory.ClickType;import net.minecraft.world.level.GameType;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.phys.*;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.network.PacketDistributor;
/** Real Survival interactions against a separate dedicated server, including full200-tick charging. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativeInfuserClientChecks {
 private static int stage,ticks,phaseTicks,captured,paused,stableWorldFrames;private static String capture;private static boolean appearance;
 private static void need(boolean ok,String why){if(!ok)throw new AssertionError("Infuser client stage="+stage+": "+why);}private static void next(int s){stage=s;phaseTicks=0;}private static void mode(int n){PacketDistributor.sendToServer(new NativeInfuserClientFixture.Mode(n));}private static boolean ack(Minecraft m,int n){return m.level.getBlockState(NativeInfuserClientFixture.ACK.east(n)).is(Blocks.STONE);}
 private static boolean pose(Minecraft m,double z,Vec3 target){return m.gameMode.getPlayerMode()==GameType.SURVIVAL&&m.player.getInventory().selected==0&&m.player.position().distanceToSqr(.5,96,z)<.01&&m.player.getLookAngle().dot(target.subtract(m.player.getEyePosition()).normalize())>.9999;}
 private static void use(Minecraft m){m.gameMode.useItemOn(m.player,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(.5,96.5,0),Direction.NORTH,NativeInfuserClientFixture.POS,false));}
 @SubscribeEvent public static void tick(ClientTickEvent.Post e){if(!NativeInfuserClientFixture.enabled())return;var m=Minecraft.getInstance();try{if(m.screen instanceof net.minecraft.client.gui.screens.AccessibilityOnboardingScreen intro){intro.onClose();return;}if(stage==16&&m.level==null){need(captured>=4,"world/iron/paused/battery actual screenshots");System.out.println("[vandorlabs][infuser-client] client PASS actualSurvivalPlacement/normalConfigurerMenus/39slots/shiftInputs/solarPauseReload/iron200/full10kPhysicalBattery/actualMining");stage=17;m.stop();return;}if(m.level==null||m.player==null||m.gameMode==null)return;need(++ticks<2600&&++phaseTicks<700,"bounded wait mode="+m.gameMode.getPlayerMode()+" selected="+m.player.getInventory().selected+" held="+m.player.getMainHandItem()+" pos="+m.player.position()+" screen="+m.screen);var gui=m.screen instanceof NativeInfuserScreen s?s:null;
 switch(stage){
  case 0->{if(!m.player.getMainHandItem().is(NativeInfuserBindings.BLOCK.asItem())||!pose(m,-3.5,new Vec3(.5,96,.5)))return;m.gameMode.useItemOn(m.player,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(.5,96,.5),Direction.UP,NativeInfuserClientFixture.POS.below(),false));next(1);}
  case 1->{if(!(m.level.getBlockEntity(NativeInfuserClientFixture.POS) instanceof NativeInfuserEntity)||!m.player.getMainHandItem().isEmpty())return;mode(0);next(2);}
  case 2->{if(!ack(m,0)||!m.player.getMainHandItem().isEmpty()||!m.player.getInventory().getItem(8).is(NativeInfuserBindings.CORE)||!pose(m,-2.5,new Vec3(.5,96.5,0)))return;capture="infuser-world.png";next(20);}
  case 20->{if(capture!=null)return;use(m);next(3);}
  case 3->{if(gui==null)return;need(gui.controlsFit()&&gui.getMenu().slots.size()==39,"ordinary vanilla furnace layout and real39 slots fit viewport");if(!appearance){NativeInfuserAppearanceChecks.verify();appearance=true;}if(!gui.getMenu().slots.get(3).getItem().is(net.minecraft.world.item.Items.IRON_INGOT)||!gui.getMenu().slots.get(4).getItem().is(net.minecraft.world.item.Items.REDSTONE_BLOCK))return;m.gameMode.handleInventoryMouseClick(gui.getMenu().containerId,3,0,ClickType.QUICK_MOVE,m.player);m.gameMode.handleInventoryMouseClick(gui.getMenu().containerId,4,0,ClickType.QUICK_MOVE,m.player);next(4);}
  case 4->{if(gui==null||gui.getMenu().value(2)<25||gui.getMenu().value(2)>160)return;need(gui.sunlight(),"solar status shows real sky availability");capture="infuser-menu-iron.png";next(21);}
  case 21->{if(capture!=null)return;mode(1);next(5);}
  case 5->{if(!ack(m,1)||gui==null||gui.sunlight())return;paused=gui.getMenu().value(2);capture="infuser-menu-paused.png";next(22);}
  case 22->{if(capture!=null||gui==null||phaseTicks<35)return;need(gui.getMenu().value(2)==paused,"real connected roof pause keeps exact cook progress");gui.onClose();mode(2);next(6);}
  case 6->{if(!ack(m,2)||!m.player.getMainHandItem().is(com.vandorlabs.neoforge.VandorLabsBootstrap.CONFIGURIZER.get())||!pose(m,-2.5,new Vec3(.5,96.5,0)))return;use(m);next(7);}
  case 7->{if(gui==null)return;need(gui.controlsFit()&&gui.getMenu().slots.size()==39,"Configurer opens same dedicated furnace menu after owner reload");if(gui.getMenu().contents().getItem(2).isEmpty())return;need(gui.getMenu().contents().getItem(2).is(com.vandorlabs.neoforge.VandorLabsBootstrap.MATTER_INGOT.get()),"ordinary recipe completes exact Matter Ingot");m.gameMode.handleInventoryMouseClick(gui.getMenu().containerId,2,0,ClickType.QUICK_MOVE,m.player);next(8);}
  case 8->{if(gui==null||!gui.getMenu().contents().getItem(2).isEmpty())return;mode(3);next(9);}
  case 9->{if(!ack(m,3)||gui==null||!NativeBatteryModule.valid(gui.getMenu().slots.get(3).getItem())||!gui.getMenu().slots.get(4).getItem().is(net.minecraft.world.item.Items.REDSTONE_BLOCK))return;m.gameMode.handleInventoryMouseClick(gui.getMenu().containerId,3,0,ClickType.QUICK_MOVE,m.player);m.gameMode.handleInventoryMouseClick(gui.getMenu().containerId,4,0,ClickType.QUICK_MOVE,m.player);next(10);}
  case 10->{if(gui==null||gui.getMenu().value(2)<30||gui.getMenu().value(2)>160)return;need(NativeBatteryModule.valid(gui.getMenu().contents().getItem(0)),"same furnace slot accepts actual physical Battery Module");capture="infuser-menu-battery.png";next(23);}
  case 23->{if(capture!=null||gui==null||NativeBatteryModule.energy(gui.getMenu().contents().getItem(2))!=10000)return;need(gui.getMenu().contents().getItem(2).getCount()==1,"charging yields one full output module");m.gameMode.handleInventoryMouseClick(gui.getMenu().containerId,2,0,ClickType.QUICK_MOVE,m.player);next(11);}
  case 11->{if(gui==null||!gui.getMenu().contents().getItem(2).isEmpty())return;gui.onClose();mode(4);next(12);}
  case 12->{if(!ack(m,4)||!m.player.getMainHandItem().is(net.minecraft.world.item.Items.IRON_PICKAXE)||!pose(m,-2.5,new Vec3(.5,96.5,0)))return;m.gameMode.startDestroyBlock(NativeInfuserClientFixture.POS,Direction.NORTH);next(13);}
  case 13->{if(!m.level.isEmptyBlock(NativeInfuserClientFixture.POS)){m.gameMode.continueDestroyBlock(NativeInfuserClientFixture.POS,Direction.NORTH);return;}m.gameMode.stopDestroyBlock();mode(5);next(14);}
  case 14->{if(!ack(m,5))return;m.level.disconnect();m.disconnect();next(16);}
 }
 }catch(Throwable bad){bad.printStackTrace();System.out.println("[vandorlabs][infuser-client] FAIL "+bad);m.stop();}}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post e)throws Exception{if(capture==null)return;var m=Minecraft.getInstance();String name=capture;if(m.getOverlay()!=null){stableWorldFrames=0;return;}if(name.contains("world")){if(++stableWorldFrames<8)return;m.getToasts().clear();m.gui.getChat().clearMessages(true);}else if(!(m.screen instanceof NativeInfuserScreen))return;capture=null;try(var image=net.minecraft.client.Screenshot.takeScreenshot(m.getMainRenderTarget())){image.writeToFile(m.gameDirectory.toPath().resolve(name));captured++;if(m.screen instanceof NativeInfuserScreen gui)NativeInfuserAppearanceChecks.verifyGuiPixels(image,gui);}}
 private NativeInfuserClientChecks(){}
}
